"use client";
import UserDropdown from "@/components/header/UserDropdown";
import { useSidebar } from "@/context/SidebarContext";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import React, { useState, useEffect, useRef } from "react";
import { Dropdown } from "@/components/ui/dropdown/Dropdown";
import { DropdownItem } from "@/components/ui/dropdown/DropdownItem";
import { searchApi } from "@/lib/api/search";
import { ApiVehicle } from "@/components/vehicle-tracking/types";
import { getCustomerTypeDisplay } from "@/components/vehicle-tracking/types";
import { AxiosError } from "axios";
import Skeleton from "@/components/ui/skeleton/Skeleton";

interface SearchResult {
  id: number;
  title: string;
  description?: string;
  href: string;
  category?: string;
}

const MIN_SEARCH_LENGTH = 2;
const DEBOUNCE_DELAY = 400;
const BLUR_DELAY = 150;

const AppHeader: React.FC = () => {
  const router = useRouter();
  const [isApplicationMenuOpen, setApplicationMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [isSearchDropdownOpen, setIsSearchDropdownOpen] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearchLoading, setIsSearchLoading] = useState(false);
  const [searchError, setSearchError] = useState<string | null>(null);
  const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const blurTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const dropdownContainerRef = useRef<HTMLDivElement | null>(null);

  const { isMobileOpen, toggleSidebar, toggleMobileSidebar } = useSidebar();

  const handleToggle = () => {
    if (window.innerWidth >= 1024) {
      toggleSidebar();
    } else {
      toggleMobileSidebar();
    }
  };

  const toggleApplicationMenu = () => {
    setApplicationMenuOpen(!isApplicationMenuOpen);
  };
  const inputRef = useRef<HTMLInputElement>(null);

  /**
   * Transform API vehicle to search result item
   */
  function transformVehicleToSearchResult(vehicle: ApiVehicle): SearchResult {
    const parts: string[] = [getCustomerTypeDisplay(vehicle.customerType)];

    if (vehicle.finalDestination) {
      parts.push(vehicle.finalDestination);
    }

    if (vehicle.route) {
      parts.push(vehicle.route);
    }

    return {
      id: vehicle.id,
      title: vehicle.referenceNumber || vehicle.vin,
      description: parts.join(" • "),
      href: `/admin/vehicle/trackings/${vehicle.id}`,
      category: "Vehicle",
    };
  }

  /**
   * Trimmed query
   */
  const trimmedQuery = searchQuery.trim();

  /**
   * Check if query is valid for search
   */
  const isValidQuery = trimmedQuery.length >= MIN_SEARCH_LENGTH;

  /**
   * Highlight matched text in a string
   */
  function highlightText(text: string, query: string): React.ReactNode {
    if (!query || query.length < MIN_SEARCH_LENGTH) {
      return text;
    }

    const escapedQuery = query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const parts = text.split(new RegExp(`(${escapedQuery})`, "gi"));
    
    return (
      <>
        {parts.map((part, index) => {
          const isMatch = part.toLowerCase() === query.toLowerCase();
          return isMatch ? (
            <mark key={index} className="bg-yellow-200 dark:bg-yellow-800 font-semibold">
              {part}
            </mark>
          ) : (
            part
          );
        })}
      </>
    );
  }

  /**
   * Perform search with request cancellation
   */
  async function performSearch(query: string) {
    // Cancel previous request if exists
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    // Create new AbortController for this request
    const abortController = new AbortController();
    abortControllerRef.current = abortController;

    setIsSearchLoading(true);
    setSearchError(null);
    setSelectedIndex(-1); // Reset selection on new search

    try {
      const vehicles = await searchApi.searchVehicles(query);
      
      // Check if request was cancelled
      if (abortController.signal.aborted) {
        return;
      }

      const results = vehicles.map(transformVehicleToSearchResult);
      setSearchResults(results);
    } catch (error) {
      // Ignore cancelled requests
      if (abortController.signal.aborted || (error as AxiosError)?.code === "ERR_CANCELED") {
        return;
      }

      const axiosError = error as AxiosError<{ message?: string }>;
      const errorMessage =
        axiosError.response?.data?.message || axiosError.message || "Failed to search vehicles";
      setSearchError(errorMessage);
      setSearchResults([]);
    } finally {
      // Only update loading state if this is still the active request
      if (!abortController.signal.aborted) {
        setIsSearchLoading(false);
      }
    }
  }

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key === "k") {
        event.preventDefault();
        inputRef.current?.focus();
        setIsSearchDropdownOpen(true);
      }
    };

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  // Cleanup timeouts and abort requests on unmount
  useEffect(() => {
    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
      if (blurTimeoutRef.current) {
        clearTimeout(blurTimeoutRef.current);
      }
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, []);

  // Scroll selected item into view
  useEffect(() => {
    if (dropdownContainerRef.current && selectedIndex >= 0 && searchResults.length > 0) {
      const items = dropdownContainerRef.current.querySelectorAll('[data-search-item]');
      const selectedItem = items[selectedIndex] as HTMLElement;
      if (selectedItem) {
        selectedItem.scrollIntoView({
          behavior: "smooth",
          block: "nearest",
        });
      }
    }
  }, [selectedIndex, searchResults.length]);

  function handleSearchChange(e: React.ChangeEvent<HTMLInputElement>) {
    const newQuery = e.target.value;
    setSearchQuery(newQuery);
    setSelectedIndex(-1);
    setSearchError(null);

    // Clear existing timeout
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    const trimmed = newQuery.trim();

    // Show dropdown if query exists
    if (trimmed.length > 0) {
      setIsSearchDropdownOpen(true);
    } else {
      setSearchResults([]);
      setIsSearchLoading(false);
      setIsSearchDropdownOpen(false);
      // Cancel any pending requests
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      return;
    }

    // Debounce search API call - only search if valid query
    if (trimmed.length >= MIN_SEARCH_LENGTH) {
      searchTimeoutRef.current = setTimeout(() => {
        performSearch(trimmed);
      }, DEBOUNCE_DELAY);
    } else {
      setSearchResults([]);
      setIsSearchLoading(false);
    }
  }

  function handleSearchFocus() {
    // Only show dropdown if there's a query or results
    if (trimmedQuery.length > 0 || searchResults.length > 0) {
      setIsSearchDropdownOpen(true);
    }
  }

  function handleSearchBlur() {
    // Clear existing blur timeout
    if (blurTimeoutRef.current) {
      clearTimeout(blurTimeoutRef.current);
    }

    // Delay closing to allow click events on dropdown items
    blurTimeoutRef.current = setTimeout(() => {
      setIsSearchDropdownOpen(false);
      setSelectedIndex(-1);
    }, BLUR_DELAY);
  }

  function closeSearchDropdown() {
    // Clear blur timeout to prevent it from reopening
    if (blurTimeoutRef.current) {
      clearTimeout(blurTimeoutRef.current);
    }
    setIsSearchDropdownOpen(false);
    setSelectedIndex(-1);
  }

  function handleItemClick(href: string, event?: React.MouseEvent) {
    // Prevent default and stop propagation if event is provided
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }
    
    // Clear blur timeout immediately to prevent dropdown from closing
    if (blurTimeoutRef.current) {
      clearTimeout(blurTimeoutRef.current);
    }
    
    closeSearchDropdown();
    router.push(href);
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (!isSearchDropdownOpen || searchResults.length === 0) {
      return;
    }

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        if (searchResults.length > 0) {
          setSelectedIndex((prev) => Math.min(prev + 1, searchResults.length - 1));
        }
        break;
      case "ArrowUp":
        e.preventDefault();
        setSelectedIndex((prev) => Math.max(prev - 1, -1));
        break;
      case "Enter":
        e.preventDefault();
        if (selectedIndex >= 0 && searchResults[selectedIndex]) {
          const selectedResult = searchResults[selectedIndex];
          handleItemClick(selectedResult.href);
        } else if (searchResults.length > 0) {
          // If no item is selected but results exist, navigate to first result
          const firstResult = searchResults[0];
          handleItemClick(firstResult.href);
        }
        break;
      case "Escape":
        e.preventDefault();
        closeSearchDropdown();
        inputRef.current?.blur();
        break;
    }
  }

  return (
    <header className="sticky top-0 flex w-full bg-white border-gray-200 z-99999 dark:border-gray-800 dark:bg-gray-900 lg:border-b">
      <div className="flex flex-col items-center justify-between grow lg:flex-row lg:px-6">
        <div className="flex items-center justify-between w-full gap-2 px-3 py-3 border-b border-gray-200 dark:border-gray-800 sm:gap-4 lg:justify-normal lg:border-b-0 lg:px-0 lg:py-4">
          <button
            className="items-center justify-center w-10 h-10 text-gray-500 border-gray-200 rounded-lg z-99999 dark:border-gray-800 lg:flex dark:text-gray-400 lg:h-11 lg:w-11 lg:border"
            onClick={handleToggle}
            aria-label="Toggle Sidebar"
          >
            {isMobileOpen ? (
              <svg
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  fillRule="evenodd"
                  clipRule="evenodd"
                  d="M6.21967 7.28131C5.92678 6.98841 5.92678 6.51354 6.21967 6.22065C6.51256 5.92775 6.98744 5.92775 7.28033 6.22065L11.999 10.9393L16.7176 6.22078C17.0105 5.92789 17.4854 5.92788 17.7782 6.22078C18.0711 6.51367 18.0711 6.98855 17.7782 7.28144L13.0597 12L17.7782 16.7186C18.0711 17.0115 18.0711 17.4863 17.7782 17.7792C17.4854 18.0721 17.0105 18.0721 16.7176 17.7792L11.999 13.0607L7.28033 17.7794C6.98744 18.0722 6.51256 18.0722 6.21967 17.7794C5.92678 17.4865 5.92678 17.0116 6.21967 16.7187L10.9384 12L6.21967 7.28131Z"
                  fill="currentColor"
                />
              </svg>
            ) : (
              <svg
                width="16"
                height="12"
                viewBox="0 0 16 12"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  fillRule="evenodd"
                  clipRule="evenodd"
                  d="M0.583252 1C0.583252 0.585788 0.919038 0.25 1.33325 0.25H14.6666C15.0808 0.25 15.4166 0.585786 15.4166 1C15.4166 1.41421 15.0808 1.75 14.6666 1.75L1.33325 1.75C0.919038 1.75 0.583252 1.41422 0.583252 1ZM0.583252 11C0.583252 10.5858 0.919038 10.25 1.33325 10.25L14.6666 10.25C15.0808 10.25 15.4166 10.5858 15.4166 11C15.4166 11.4142 15.0808 11.75 14.6666 11.75L1.33325 11.75C0.919038 11.75 0.583252 11.4142 0.583252 11ZM1.33325 5.25C0.919038 5.25 0.583252 5.58579 0.583252 6C0.583252 6.41421 0.919038 6.75 1.33325 6.75L7.99992 6.75C8.41413 6.75 8.74992 6.41421 8.74992 6C8.74992 5.58579 8.41413 5.25 7.99992 5.25L1.33325 5.25Z"
                  fill="currentColor"
                />
              </svg>
            )}
            {/* Cross Icon */}
          </button>

          <Link href="/" className="lg:hidden">
            <Image
              width={154}
              height={32}
              className="dark:hidden"
              src="./images/logo/logo.svg"
              alt="Logo"
              draggable={false}
            />
            <Image
              width={154}
              height={32}
              className="hidden dark:block"
              src="./images/logo/logo-dark.svg"
              alt="Logo"
              draggable={false}
            />
          </Link>

          <button
            onClick={toggleApplicationMenu}
            className="flex items-center justify-center w-10 h-10 text-gray-700 rounded-lg z-99999 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-800 lg:hidden"
          >
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                fillRule="evenodd"
                clipRule="evenodd"
                d="M5.99902 10.4951C6.82745 10.4951 7.49902 11.1667 7.49902 11.9951V12.0051C7.49902 12.8335 6.82745 13.5051 5.99902 13.5051C5.1706 13.5051 4.49902 12.8335 4.49902 12.0051V11.9951C4.49902 11.1667 5.1706 10.4951 5.99902 10.4951ZM17.999 10.4951C18.8275 10.4951 19.499 11.1667 19.499 11.9951V12.0051C19.499 12.8335 18.8275 13.5051 17.999 13.5051C17.1706 13.5051 16.499 12.8335 16.499 12.0051V11.9951C16.499 11.1667 17.1706 10.4951 17.999 10.4951ZM13.499 11.9951C13.499 11.1667 12.8275 10.4951 11.999 10.4951C11.1706 10.4951 10.499 11.1667 10.499 11.9951V12.0051C10.499 12.8335 11.1706 13.5051 11.999 13.5051C12.8275 13.5051 13.499 12.8335 13.499 12.0051V11.9951Z"
                fill="currentColor"
              />
            </svg>
          </button>

          <div className="hidden lg:block">
            <div className="relative search-container">
              {/* <form>
                <div className="relative">
                  <span className="absolute -translate-y-1/2 left-4 top-1/2 pointer-events-none">
                    <svg
                      className="fill-gray-500 dark:fill-gray-400"
                      width="20"
                      height="20"
                      viewBox="0 0 20 20"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                    >
                      <path
                        fillRule="evenodd"
                        clipRule="evenodd"
                        d="M3.04175 9.37363C3.04175 5.87693 5.87711 3.04199 9.37508 3.04199C12.8731 3.04199 15.7084 5.87693 15.7084 9.37363C15.7084 12.8703 12.8731 15.7053 9.37508 15.7053C5.87711 15.7053 3.04175 12.8703 3.04175 9.37363ZM9.37508 1.54199C5.04902 1.54199 1.54175 5.04817 1.54175 9.37363C1.54175 13.6991 5.04902 17.2053 9.37508 17.2053C11.2674 17.2053 13.003 16.5344 14.357 15.4176L17.177 18.238C17.4699 18.5309 17.9448 18.5309 18.2377 18.238C18.5306 17.9451 18.5306 17.4703 18.2377 17.1774L15.418 14.3573C16.5365 13.0033 17.2084 11.2669 17.2084 9.37363C17.2084 5.04817 13.7011 1.54199 9.37508 1.54199Z"
                        fill=""
                      />
                    </svg>
                  </span>
                  <input
                    ref={inputRef}
                    type="text"
                    value={searchQuery}
                    onChange={handleSearchChange}
                    onFocus={handleSearchFocus}
                    onBlur={handleSearchBlur}
                    onKeyDown={handleKeyDown}
                    placeholder="Search or type command..."
                    className="dark:bg-dark-900 h-11 w-full rounded-lg border border-gray-200 bg-transparent py-2.5 pl-12 pr-14 text-sm text-gray-800 shadow-theme-xs placeholder:text-gray-400 focus:border-brand-300 focus:outline-hidden focus:ring-3 focus:ring-brand-500/10 dark:border-gray-800 dark:bg-white/3 dark:text-white/90 dark:placeholder:text-white/30 dark:focus:border-brand-800 xl:w-[430px]"
                  />

                  <button className="absolute right-2.5 top-1/2 inline-flex -translate-y-1/2 items-center gap-0.5 rounded-lg border border-gray-200 bg-gray-50 px-[7px] py-[4.5px] text-xs -tracking-[0.2px] text-gray-500 dark:border-gray-800 dark:bg-white/3 dark:text-gray-400">
                    <span> ⌘ </span>
                    <span> K </span>
                  </button>
                </div>
              </form> */}

              <Dropdown
                isOpen={
                  isSearchDropdownOpen &&
                  trimmedQuery.length > 0 &&
                  (isSearchLoading || searchResults.length > 0 || !!searchError || !isValidQuery)
                }
                onClose={closeSearchDropdown}
                className="left-0 top-full mt-2 w-full xl:w-[430px] max-h-[400px] overflow-y-auto"
              >
                <div className="p-2" ref={dropdownContainerRef}>
                  {!isValidQuery ? (
                    <div className="px-3 py-4 text-sm text-gray-500 dark:text-gray-400">
                      Type at least {MIN_SEARCH_LENGTH} characters to search
                    </div>
                  ) : isSearchLoading ? (
                    <>
                      {[1, 2, 3].map((index) => (
                        <div key={index} className="flex flex-col gap-2 px-3 py-2.5 rounded-lg mb-2 last:mb-0">
                          <div className="flex items-center justify-between">
                            <Skeleton variant="text" height={16} width="40%" />
                            <Skeleton variant="text" height={12} width="15%" />
                          </div>
                          <Skeleton variant="text" height={12} width="70%" />
                        </div>
                      ))}
                    </>
                  ) : searchError ? (
                    <div className="px-3 py-4 text-sm text-red-600 dark:text-red-400">{searchError}</div>
                  ) : searchResults.length > 0 ? (
                    searchResults.map((result, index) => (
                      <div key={result.id} data-search-item>
                        <DropdownItem
                          tag="button"
                          onItemClick={(e) => handleItemClick(result.href, e)}
                          className={`flex flex-col gap-1 px-3 py-2.5 rounded-lg w-full ${
                            index === selectedIndex
                              ? "bg-brand-500/10 text-brand-700 dark:bg-brand-800/20 dark:text-brand-400"
                              : "text-gray-700 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-white/5"
                          }`}
                        >
                        <div className="flex items-center justify-between">
                          <span className="font-medium text-sm">{highlightText(result.title, trimmedQuery)}</span>
                          {result.category && (
                            <span className="text-xs text-gray-500 dark:text-gray-400">{result.category}</span>
                          )}
                        </div>
                        {result.description && (
                          <span className="text-xs text-gray-500 dark:text-gray-400">{result.description}</span>
                        )}
                        </DropdownItem>
                      </div>
                    ))
                  ) : (
                    <div className="px-3 py-4 text-sm text-gray-500 dark:text-gray-400">No vehicles found</div>
                  )}
                </div>
              </Dropdown>
            </div>
          </div>
        </div>
        <div
          className={`${
            isApplicationMenuOpen ? "flex" : "hidden"
          } items-center justify-between w-full gap-4 px-5 py-4 lg:flex shadow-theme-md lg:justify-end lg:px-0 lg:shadow-none`}
        >
          <div className="flex items-center gap-2 2xsm:gap-3">
            {/* Notification and theme toggle area */}
          </div>
          {/* <!-- User Area --> */}
          <UserDropdown /> 
    
        </div>
      </div>
    </header>
  );
};

export default AppHeader;
